import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    target_state = target_state.reset_index(drop=True)
    cdc_events = cdc_events.reset_index(drop=True)

    # Remember original dtypes for output coercion
    orig_order_id_dtype = target_state["order_id"].dtype if "order_id" in target_state.columns else np.int64
    orig_status_dtype = target_state["status"].dtype if "status" in target_state.columns else object
    orig_amount_dtype = target_state["amount"].dtype if "amount" in target_state.columns else np.float64
    orig_last_seq_dtype = target_state["last_seq"].dtype if "last_seq" in target_state.columns else np.int64
    orig_seq_dtype = cdc_events["seq"].dtype if "seq" in cdc_events.columns else np.int64

    # ---- Step 1: distinct events by seq (at-least-once delivery) ----
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Sort by seq ascending -- the only trustworthy order
    cdc_events = cdc_events.sort_values("seq", kind="mergesort").reset_index(drop=True)

    # ---- Build initial state dict from target_state ----
    # state[order_id] = {
    #    'exists': bool,
    #    'status': ...,
    #    'amount': ...,
    #    'last_seq': ...,
    #    'deleted_seq': ... (meaningful when not exists but had a row before)
    # }
    state = {}
    target_last_seq = {}  # original watermark map, used only for the replay guard

    for _, row in target_state.iterrows():
        oid = row["order_id"]
        state[oid] = {
            "exists": True,
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
            "deleted_seq": None,
        }
        target_last_seq[oid] = row["last_seq"]

    # ---- Step 2: replay guard filter (based on ORIGINAL target_state only) ----
    def passes_guard(oid, seq):
        if oid in target_last_seq:
            return seq > target_last_seq[oid]
        return True

    keep_mask = [
        passes_guard(oid, seq)
        for oid, seq in zip(cdc_events["order_id"], cdc_events["seq"])
    ]
    filtered = cdc_events[pd.Series(keep_mask, index=cdc_events.index)]

    # ---- Step 3: apply remaining events in seq order ----
    for _, ev in filtered.iterrows():
        oid = ev["order_id"]
        op = ev["op"]
        seq = ev["seq"]
        status = ev["status"]
        amount = ev["amount"]

        if oid not in state:
            state[oid] = {
                "exists": False,
                "status": None,
                "amount": None,
                "last_seq": None,
                "deleted_seq": None,
            }

        entry = state[oid]

        if op == "D":
            if entry["exists"]:
                entry["exists"] = False
                entry["status"] = None
                entry["amount"] = None
                entry["last_seq"] = None
                entry["deleted_seq"] = seq
            else:
                # D on a missing order does nothing
                pass
        else:
            # 'I' or 'U'
            if entry["exists"]:
                new_status = status
                if op == "U" and pd.isna(amount):
                    new_amount = entry["amount"]
                else:
                    new_amount = amount
                entry["status"] = new_status
                entry["amount"] = new_amount
                entry["last_seq"] = seq
                # row now exists -> clear any stale deleted_seq
                entry["deleted_seq"] = None
            else:
                # creation: amount taken as-is regardless of op
                entry["exists"] = True
                entry["status"] = status
                entry["amount"] = amount
                entry["last_seq"] = seq
                entry["deleted_seq"] = None

    # ---- Step 4 & 5: build outputs ----
    new_rows = []
    tomb_rows = []

    for oid, entry in state.items():
        if entry["exists"]:
            new_rows.append({
                "order_id": oid,
                "status": entry["status"],
                "amount": entry["amount"],
                "last_seq": entry["last_seq"],
            })
        else:
            if entry["deleted_seq"] is not None:
                tomb_rows.append({
                    "order_id": oid,
                    "deleted_seq": entry["deleted_seq"],
                })

    new_state = pd.DataFrame(new_rows, columns=["order_id", "status", "amount", "last_seq"])
    tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])

    # ---- dtype coercion ----
    if not new_state.empty:
        try:
            new_state["order_id"] = new_state["order_id"].astype(orig_order_id_dtype)
        except (ValueError, TypeError):
            pass
        try:
            new_state["status"] = new_state["status"].astype(orig_status_dtype)
        except (ValueError, TypeError):
            pass
        try:
            new_state["amount"] = new_state["amount"].astype(orig_amount_dtype)
        except (ValueError, TypeError):
            pass
        try:
            new_state["last_seq"] = new_state["last_seq"].astype(orig_last_seq_dtype)
        except (ValueError, TypeError):
            pass
    else:
        new_state = pd.DataFrame({
            "order_id": pd.Series(dtype=orig_order_id_dtype),
            "status": pd.Series(dtype=orig_status_dtype),
            "amount": pd.Series(dtype=orig_amount_dtype),
            "last_seq": pd.Series(dtype=orig_last_seq_dtype),
        })

    if not tombstones.empty:
        try:
            tombstones["order_id"] = tombstones["order_id"].astype(orig_order_id_dtype)
        except (ValueError, TypeError):
            pass
        try:
            tombstones["deleted_seq"] = tombstones["deleted_seq"].astype(orig_seq_dtype)
        except (ValueError, TypeError):
            pass
    else:
        tombstones = pd.DataFrame({
            "order_id": pd.Series(dtype=orig_order_id_dtype),
            "deleted_seq": pd.Series(dtype=orig_seq_dtype),
        })

    return {"new_state": new_state, "tombstones": tombstones}
